      const maxPolls = options.timeout !== undefined ? Math.max(1, Math.ceil(parsePositiveNumber(options.timeout, "--timeout") * 1000 / pollIntervalMs)) : Math.ceil(DEFAULT_TIMEOUT_MS / pollIntervalMs);
