async function provisionFolder(folderKey, orchOptions) {
  const foldersApi = await createApiClient(FoldersApi, orchOptions);
  const folderResult = await foldersApi.foldersGet({
    $filter: `Key eq '${folderKey}'`,
    $top: 1
  });
  const folder = folderResult.value?.[0];
  if (!folder?.id) {
    throw new Error(`Folder ${folderKey} not found in Orchestrator`);
  }
  const folderId = folder.id;
  const machinesApi = await createApiClient(MachinesApi, orchOptions);
  const machinesResult = await machinesApi.machinesGet({
    $filter: "Scope eq 'Serverless'",
    $top: 1
  });
  const serverless = machinesResult.value?.[0];
  if (!serverless?.id) {
    throw new Error("No serverless machine template found in tenant");
  }
  const [machineAssignError] = await catchError(foldersApi.foldersAssignMachines({
    body: {
      assignments: {
        machineIds: [serverless.id],
        folderIds: [folderId]
      }
    }
  }));
  if (machineAssignError && !hasResponseStatus(machineAssignError, 409)) {
    throw machineAssignError;
  }
  const assignableUsers = await foldersApi.foldersGetUsersToAssignByFolderid({
    folderId,
    $top: 100
  });
  const robotUser = assignableUsers.value?.find((user) => user.id != null && user.userName);
  if (!robotUser?.id) {
    throw new Error("No robot user found in tenant");
  }
  const rolesResult = await foldersApi.foldersGetAllRolesForUserByUsernameAndSkipAndTake({
    username: robotUser.userName ?? "",
    skip: 0,
    take: 100
  });
  const automationRole = rolesResult.tenantRoles?.find((r) => r.name === "Automation User");
  if (!automationRole?.id) {
    throw new Error("'Automation User' role not found");
  }
  const [userAssignError] = await catchError(foldersApi.foldersAssignUsers({
    body: {
      assignments: {
        userIds: [robotUser.id],
        rolesPerFolder: [
          {
            folderId,
            roleIds: [automationRole.id]
          }
        ]
      }
    }
  }));
  if (userAssignError && !hasResponseStatus(userAssignError, 409)) {
    throw userAssignError;
  }
  return {
    folderId,
    machineName: serverless.name,
    userName: robotUser.userName ?? "robot"
  };
}
