      const service = new EvalService;
      const evaluation = await service.addEvaluation(options.path, options.set, {
        name,
        inputs,
        expectedOutput,
        expectedAgentBehavior: options.expectedAgentBehavior,
        simulationInstructions: options.simulationInstructions,
        simulateInput: options.simulateInput,
        simulateTools: options.simulateTools,
        inputGenerationInstructions: options.inputGenerationInstructions
      });
