var VALID_NAME_REGEX = /^[a-zA-Z0-9_ -]+$/;
var INIT_EXAMPLES = [
  {
    Description: "Scaffold a new standalone autonomous agent project",
    Command: "uip agent init ./my-agent --model gpt-5.4",
    Output: {
      Code: "AgentInit",
      Data: {
        Status: "Agent project created",
        Path: "./my-agent",
        Name: "my-agent",
        Model: "gpt-5.4",
        ProjectId: "a1b2c3d4-0000-0000-0000-000000000301"
      }
    }
  },
  {
    Description: "Scaffold a new standalone conversational agent project",
    Command: "uip agent init ./my-agent --conversational --model anthropic.claude-sonnet-4-5-20250929-v1:0",
    Output: {
      Code: "AgentInit",
      Data: {
        Status: "Agent project created",
        Path: "./my-agent",
        Name: "my-agent",
        Model: "anthropic.claude-sonnet-4-5-20250929-v1:0",
        ProjectId: "a1b2c3d4-0000-0000-0000-000000000302"
      }
    }
  }
];
var registerInitCommand = (program) => {
  program.command("init").description("Scaffold a new agent project at the given path. " + "When run inside a solution directory, the project is auto-registered in the " + "surrounding solution's .uipx. When run outside any solution, a parent " + "'<name>Solution' is scaffolded automatically and the agent project is nested " + `inside it (pass --skip-solution-registration to opt out of both behaviors).
` + "With --inline-in-flow, scaffolds an inline agent inside a flow project instead " + "(UUID-named subdirectory, no entry-points/project.uiproj, empty flow-layout.json).").argument("<path>", "Target directory for the agent project (relative or absolute). " + "When --inline-in-flow is used, this is the flow project directory.").option("--conversational", "Scaffold a conversational agent. When not provided, defaults to an autonomous agent.").option("--model <model>", "LLM model to use. When not provided, uses recommended default for " + "autonomous/conversational agent.").option("--system-prompt <prompt>", "Initial system prompt for the agent").option("--force", "Overwrite existing directory if non-empty").option("--skip-solution-registration", "Do not auto-register this project in the surrounding solution").option("--inline-in-flow", "Scaffold an inline agent inside a flow project. " + "The <path> argument becomes the flow project directory. " + "Creates a UUID-named subdirectory with agent.json, empty flow-layout.json, " + "and empty evals/features/resources folders.").examples(INIT_EXAMPLES).trackedAction(processContext, async (targetPath, options) => {
    const [error] = await catchError(options.inlineInFlow === true ? scaffoldInlineAgent(targetPath, options) : scaffoldStandaloneAgent(targetPath, options));
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: options.inlineInFlow === true ? "Failed to initialize inline agent" : "Failed to initialize agent project",
        Instructions: error.message
      });
      processContext.exit(1);
    }
  });
};
async function scaffoldStandaloneAgent(targetPath, options) {
  const fs7 = getFileSystem();
  const candidateProjectDir = fs7.path.resolve(targetPath);
  const name = fs7.path.basename(candidateProjectDir);
  if (!VALID_NAME_REGEX.test(name)) {
    throw new Error(`Invalid agent name "${name}" derived from path. ` + "Directory name may only contain letters, numbers, spaces, underscores, and hyphens.");
  }
  const { projectDir, autoCreatedSolution } = await prepareProjectLocation(fs7, candidateProjectDir, name, { skipRegistration: options.skipSolutionRegistration === true });
  const dirExists = await fs7.exists(projectDir);
  if (dirExists && !options.force) {
    const entries = await fs7.readdir(projectDir);
    if (entries.length > 0) {
      throw new Error(`Directory "${projectDir}" already exists and is not empty. Use --force to overwrite.`);
    }
  }
  const projectId = crypto.randomUUID();
  const entryPointId = crypto.randomUUID();
  const semanticEvalId = crypto.randomUUID();
  const trajectoryEvalId = crypto.randomUUID();
  const evalSetId = crypto.randomUUID();
  const agent = createAgentDefinition({
    projectId,
    conversational: options.conversational,
    model: options.model,
    systemPrompt: options.systemPrompt
  });
  const entryPoints = createEntryPoints({
    uniqueId: entryPointId,
    inputSchema: agent.inputSchema,
    outputSchema: agent.outputSchema
  });
  const semanticEval = createDefaultSemanticEvaluator(semanticEvalId);
  const trajectoryEval = createDefaultTrajectoryEvaluator(trajectoryEvalId);
  const evalSet = createDefaultEvaluationSet({
    id: evalSetId,
    evaluatorIds: [semanticEvalId, trajectoryEvalId]
  });
  await fs7.mkdir(projectDir);
  await fs7.mkdir(fs7.path.join(projectDir, "evals", "evaluators"));
  await fs7.mkdir(fs7.path.join(projectDir, "evals", "eval-sets"));
  await fs7.mkdir(fs7.path.join(projectDir, "features"));
  await fs7.mkdir(fs7.path.join(projectDir, "resources"));
  const write = async (path3, data2) => fs7.writeFile(path3, `${JSON.stringify(data2, null, 2)}
`);
  await write(fs7.path.join(projectDir, "agent.json"), agent);
  await write(fs7.path.join(projectDir, "project.uiproj"), createProjectUiproj(name));
  await write(fs7.path.join(projectDir, "entry-points.json"), entryPoints);
  await write(fs7.path.join(projectDir, "flow-layout.json"), createFlowLayout());
  await write(fs7.path.join(projectDir, "evals", "evaluators", semanticEval.fileName), semanticEval);
  await write(fs7.path.join(projectDir, "evals", "evaluators", trajectoryEval.fileName), trajectoryEval);
  await write(fs7.path.join(projectDir, "evals", "eval-sets", "evaluation-set-default.json"), evalSet);
  const solutionRegistration = await tryRegisterProjectInParentSolution(fs7, projectDir, { skipRegistration: options.skipSolutionRegistration === true });
  let projectArtifacts;
  if ((solutionRegistration.Status === "Registered" || solutionRegistration.Status === "AlreadyRegistered") && solutionRegistration.Solution && solutionRegistration.ProjectId) {
    projectArtifacts = await ensureProjectArtifacts({
      solutionDir: fs7.path.dirname(solutionRegistration.Solution),
      projectId: solutionRegistration.ProjectId,
      projectName: name,
      projectType: "Agent"
    });
  }
  const data = {
    Status: "Agent project created",
    Path: projectDir,
    Name: name,
    Model: agent.settings.model,
    ProjectId: projectId,
    NextSteps: buildStandaloneNextSteps(projectDir, solutionRegistration),
    SolutionRegistration: solutionRegistration
  };
  if (autoCreatedSolution) {
    data.AutoCreatedSolution = autoCreatedSolution;
  }
  if (projectArtifacts) {
    data.ProjectArtifacts = projectArtifacts;
  }
  OutputFormatter.success({
    Result: RESULTS.Success,
    Code: "AgentInit",
    Data: data
  });
}
function buildStandaloneNextSteps(projectPath, solutionRegistration) {
  const steps = ["# Edit agent.json to configure prompts and resources"];
  if (solutionRegistration.Status === "OptedOut") {
    steps.push("# Solution auto-registration was skipped (--skip-solution-registration)");
  }
  if (solutionRegistration.Status === "Registered" || solutionRegistration.Status === "AlreadyRegistered") {
    steps.push("# The project is already registered in the parent solution", "# Run refresh to generate entry-points.json and bindings_v2.json:", `uip agent refresh ${JSON.stringify(projectPath)}`, "# Then validate the project is ready for upload:", `uip agent validate ${JSON.stringify(projectPath)}`, "# Pack or upload the solution from the solution directory:", "uip solution pack . ./dist", "uip solution upload .");
    return steps.join(`
`);
  }
  steps.push("# Then link to a solution:", 'uip solution init "<SolutionName>"', `uip solution projects add ${JSON.stringify(projectPath)} <SolutionName>.uipx`, "# Or if the solution already exists:", `uip solution projects add ${JSON.stringify(projectPath)} <existing>.uipx`, "# Run refresh to generate entry-points.json and bindings_v2.json:", `uip agent refresh ${JSON.stringify(projectPath)}`, "# Then validate the project is ready for upload:", `uip agent validate ${JSON.stringify(projectPath)}`, "# Bundle and upload to Studio Web:", "uip solution bundle . -d ./dist", "uip solution upload ./dist/<SolutionName>.uis");
  return steps.join(`
`);
}
async function scaffoldInlineAgent(targetPath, options) {
  const fs7 = getFileSystem();
  const flowProjectDir = fs7.path.resolve(targetPath);
  const dirExists = await fs7.exists(flowProjectDir);
  if (!dirExists) {
    throw new Error(`Flow project directory "${flowProjectDir}" does not exist. ` + "Create a flow project first with 'uip maestro flow init'.");
  }
  const projectId = crypto.randomUUID();
  const agentDir = fs7.path.join(flowProjectDir, projectId);
  const agent = createInlineAgentDefinition({
    projectId,
    conversational: options.conversational,
    model: options.model
  });
  await fs7.mkdir(agentDir);
  await fs7.mkdir(fs7.path.join(agentDir, "evals", "eval-sets"));
  await fs7.mkdir(fs7.path.join(agentDir, "features"));
  await fs7.mkdir(fs7.path.join(agentDir, "resources"));
  const write = async (path3, data) => fs7.writeFile(path3, `${JSON.stringify(data, null, 2)}
`);
  await write(fs7.path.join(agentDir, "agent.json"), agent);
  await write(fs7.path.join(agentDir, "flow-layout.json"), {});
  OutputFormatter.success({
    Result: RESULTS.Success,
    Code: "AgentInitInline",
    Data: {
      Status: "Inline agent created inside flow project",
      Path: agentDir,
      ProjectId: projectId,
      Model: agent.settings.model,
      NextSteps: [
        "# Edit agent.json to configure prompts and settings",
        "# Add an inline agent node to the flow referencing this agent:",
        "# The node must have model.source = projectId in the .flow JSON",
        "# Use the uipath-flow skill for flow node wiring guidance",
        "# Run refresh to migrate and generate bindings_v2.json in the parent flow:",
        `uip agent refresh ${JSON.stringify(agentDir)} --inline-in-flow`,
        "# Then validate the inline agent is ready for upload:",
        `uip agent validate ${JSON.stringify(agentDir)} --inline-in-flow`
      ].join(`
`)
    }
  });
}

