var registerListCommand = (program) => {
  program.command("list").description("[DEPRECATED] List solutions from Studio Web").option("-s, --search <query>", "Keyword filter for search").option("-l, --limit <n>", "Maximum number of results", (v) => Number.parseInt(v, 10), 20).option("--login-validity <minutes>", "Minimum minutes before token expiration", (v) => Number.parseInt(v, 10), 10).examples(LIST_EXAMPLES).trackedAction(processContext, async (options) => {
    const [error] = await catchError((async () => {
      const loginStatus = await getLoginStatusAsync({
        ensureTokenValidityMinutes: options.loginValidity
      });
      if (loginStatus.loginStatus !== "Logged in" || !loginStatus.accessToken || !loginStatus.baseUrl || !loginStatus.organizationId) {
        throw new Error("Not logged in. Run 'uip login' first.");
      }
      const backendBase = `${loginStatus.baseUrl}/${loginStatus.organizationId}/studio_/backend`;
      const params = new URLSearchParams({
        "pagingOptions.limit": String(options.limit),
        "pagingOptions.skip": "0"
      });
      if (options.search) {
        params.set("keywords", options.search);
      }
      const url = `${backendBase}/api/Solution/SearchSolutionsAndProjects?${params.toString()}`;
      const response = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${loginStatus.accessToken}`
        }
      });
      if (!response.ok) {
        const text = await response.text();
        throw new Error(`Studio Web API returned ${response.status}: ${text}`);
      }
      const body = await response.json();
      const solutions = body.solutions ?? body.data ?? body ?? [];
      const items = Array.isArray(solutions) ? solutions : [];
      if (items.length === 0) {
        OutputFormatter.success({
          Result: RESULTS.Success,
          Code: "AgentList",
          Data: { Message: "No solutions found" }
        });
        return;
      }
      OutputFormatter.success({
        Result: RESULTS.Success,
        Code: "AgentList",
        Data: items.map((s) => ({
          Name: s.name ?? s.Name ?? "",
          Id: s.id ?? s.Id ?? "",
          Status: s.status ?? s.Status ?? "",
          PublishStatus: s.publishStatus ?? s.PublishStatus ?? "",
          LastModified: s.lastModified ?? s.LastModified ?? "",
          Projects: (s.projects ?? s.Projects ?? []).length
        }))
      });
    })());
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to list solutions",
        Instructions: error.message
      });
      processContext.exit(1);
    }
  });
};

