function collectOption(value, previous = []) {
  return [...previous, value];
}
function parseNumberOption(value, optionName) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) {
    throw new Error(`Invalid ${optionName} value: "${value}"`);
  }
  return parsed;
}
function parseIntegerOption(value, optionName) {
  const parsed = parseNumberOption(value, optionName);
  if (!Number.isInteger(parsed)) {
    throw new Error(`Invalid ${optionName} value: "${value}"`);
  }
  return parsed;
}
function parsePositiveIntegerOption(value, optionName) {
  const parsed = parseIntegerOption(value, optionName);
  if (parsed < 1) {
    throw new Error(`Invalid ${optionName} value: "${value}". Must be greater than or equal to 1.`);
  }
  return parsed;
}
function parseSearchMode(value) {
  if (VALID_SEARCH_MODES.includes(value)) {
    return value;
  }
  throw new Error(`Invalid search-mode value: "${value}". Valid values: ${VALID_SEARCH_MODES.join(", ")}`);
}
function parseMemoryType(value) {
  const memoryType = MEMORY_TYPE_VALUES[value.toLowerCase()];
  if (memoryType !== undefined) {
    return memoryType;
  }
  throw new Error(`Invalid memory-type value: "${value}". Valid values: episodic, escalation, 0, 1`);
}
function parseFieldSettings(fields) {
  return fields.map((field) => {
    const parts = field.split("=");
    if (parts.length !== 2) {
      throw new Error(`Invalid field value: "${field}". Use the form <fieldName>=<weight>.`);
    }
    const [name, weightValue] = parts;
    if (!name) {
      throw new Error(`Invalid field value: "${field}". Field name is required.`);
    }
    if (!weightValue) {
      throw new Error(`Invalid field value: "${field}". Field weight is required.`);
    }
    const weight = parseNumberOption(weightValue, "field weight");
    return { name, weight };
  });
}
function parseMetadata(value) {
  if (value === undefined)
    return;
  const [error, parsed] = catchError(() => JSON.parse(value));
  if (error) {
    throw new Error(`Invalid metadata JSON: ${error.message}`);
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Invalid metadata JSON: expected an object.");
  }
  return parsed;
}
