// src/services/schema-validation-service.ts
async function loadMigrationModule() {
  return await import("./index-t82tsh16.js");
}
function formatPath(path3) {
  return path3.map((p) => typeof p === "number" ? `[${p}]` : `.${p}`).join("").replace(/^\./, "");
}
function isVersionNewer(v1, v2) {
  const parse = (v) => v.split(".").map((n) => parseInt(n, 10) || 0);
  const [maj1 = 0, min1 = 0, pat1 = 0] = parse(v1);
  const [maj2 = 0, min2 = 0, pat2 = 0] = parse(v2);
  if (maj1 !== maj2)
    return maj1 > maj2;
  if (min1 !== min2)
    return min1 > min2;
  return pat1 > pat2;
}
function detectStorageVersion(agentJson) {
  const metadata = agentJson.metadata;
  if (metadata?.storageVersion && typeof metadata.storageVersion === "string") {
    return metadata.storageVersion;
  }
  if (typeof agentJson.version === "string") {
    return agentJson.version;
  }
  return "0.0.0";
}
function formatContent(content) {
  if (typeof content === "string") {
    try {
      return `${JSON.stringify(JSON.parse(content), null, 2)}
`;
    } catch {
      return `${content}
`;
    }
  }
  return `${JSON.stringify(content, null, 2)}
`;
}
async function readFolderRecursive(name, dirPath, fs7) {
  const folder = { name, folders: [], files: [] };
  let entries;
  try {
    entries = await fs7.readdir(dirPath);
  } catch {
    return folder;
  }
  for (const entry of entries) {
    const entryPath = fs7.path.join(dirPath, entry);
    const stats = await fs7.stat(entryPath);
    if (!stats)
      continue;
    if (stats.isFile()) {
      const content = await fs7.readFile(entryPath, "utf-8");
      if (content !== null) {
        folder.files.push({ name: entry, content });
      }
    } else if (stats.isDirectory()) {
      folder.folders.push(await readFolderRecursive(entry, entryPath, fs7));
    }
  }
  return folder;
}
async function readFilesystemTree(agentDir, fs7) {
  const agentJsonRaw = await fs7.readFile(fs7.path.join(agentDir, "agent.json"), "utf-8");
  const flowLayoutRaw = await fs7.readFile(fs7.path.join(agentDir, "flow-layout.json"), "utf-8");
  const files = [];
  if (agentJsonRaw)
    files.push({ name: "agent.json", content: agentJsonRaw });
  if (flowLayoutRaw)
    files.push({ name: "flow-layout.json", content: flowLayoutRaw });
  const folders = await Promise.all(["evals", "features", "resources"].map((folderName) => readFolderRecursive(folderName, fs7.path.join(agentDir, folderName), fs7)));
  return { folders, files };
}
function preMigrationRecovery(tree) {
  const result = { ...tree };
  const existingNames = new Set(result.folders.map((f) => f.name));
  const toAdd = [];
  if (!existingNames.has("resources")) {
    toAdd.push({ name: "resources", folders: [], files: [] });
  } else {
    result.folders = result.folders.map((folder) => {
      if (folder.name !== "resources")
        return folder;
      return {
        ...folder,
        folders: folder.folders.filter((resourceFolder) => {
          const resourceFile = resourceFolder.files.find((f) => f.name === "resource.json");
          if (!resourceFile)
            return true;
          try {
            const parsed = typeof resourceFile.content === "string" ? JSON.parse(resourceFile.content) : resourceFile.content;
            return parsed && typeof parsed === "object" && "$resourceType" in parsed;
          } catch {
            return false;
          }
        })
      };
    });
  }
  if (!existingNames.has("features")) {
    toAdd.push({ name: "features", folders: [], files: [] });
  }
  if (!existingNames.has("evals")) {
    toAdd.push({
      name: "evals",
      folders: [
        { name: "eval-sets", folders: [], files: [] },
        { name: "evaluators", folders: [], files: [] }
      ],
      files: []
    });
  }
  if (toAdd.length > 0) {
    result.folders = [...result.folders, ...toAdd];
  }
  result.folders = [...result.folders].sort((a, b) => a.name.localeCompare(b.name));
  if (!result.files.some((f) => f.name === "flow-layout.json")) {
    result.files = [
      ...result.files,
      { name: "flow-layout.json", content: "{}" }
    ];
  }
  result.files = [...result.files].sort((a, b) => {
    if (a.name === "agent.json")
      return -1;
    if (b.name === "agent.json")
      return 1;
    if (a.name === "flow-layout.json")
      return -1;
    if (b.name === "flow-layout.json")
      return 1;
    return a.name.localeCompare(b.name);
  });
  return result;
}
async function discoverAgentDirs(projectPath) {
  const fs7 = getFileSystem();
  const flatAgent = fs7.path.join(projectPath, "agent.json");
  if (await fs7.exists(flatAgent)) {
    return ["."];
  }
  try {
    const entries = await fs7.readdir(projectPath);
    const agentDirs = [];
    for (const entry of entries) {
      if (await fs7.exists(fs7.path.join(projectPath, entry, "agent.json"))) {
        agentDirs.push(entry);
      }
    }
    return agentDirs;
  } catch {
    return [];
  }
}
function collectMigratedFiles(agentDir, tree, fs7) {
  const result = [];
  for (const file of tree.files) {
    result.push({
      filePath: fs7.path.join(agentDir, file.name),
      content: formatContent(file.content)
    });
  }
  function walkFolder(basePath, folder) {
    for (const file of folder.files) {
      result.push({
        filePath: fs7.path.join(basePath, file.name),
        content: formatContent(file.content)
      });
    }
    for (const sub of folder.folders) {
      walkFolder(fs7.path.join(basePath, sub.name), sub);
    }
  }
  for (const folder of tree.folders) {
    walkFolder(fs7.path.join(agentDir, folder.name), folder);
  }
  return result;
}
async function validateAgentSchema(projectPath) {
  const issues = [];
  const warnings = [];
  const validated = {
    agent: false,
    resources: 0,
    evalSets: 0,
    evaluators: 0
  };
  let migrationApplied = false;
  const fs7 = getFileSystem();
  const migration = await loadMigrationModule();
  const schemaVersion = migration.getLatestVersion(migration.migrations);
  const agentDirs = await discoverAgentDirs(projectPath);
  if (agentDirs.length === 0) {
    issues.push({
      file: projectPath,
      path: "",
      message: "No agent directories found. Expected Agent/ directory or directories containing agent.json"
    });
    return {
      valid: false,
      schemaVersion,
      issues,
      warnings,
      validated,
      migratedFiles: [],
      migrationApplied
    };
  }
  const pendingTrees = [];
  for (const dirName of agentDirs) {
    const agentDir = fs7.path.join(projectPath, dirName);
    const agentJsonRaw = await fs7.readFile(fs7.path.join(agentDir, "agent.json"), "utf-8");
    if (!agentJsonRaw) {
      issues.push({
        file: `${dirName}/agent.json`,
        path: "",
        message: "File not found or empty"
      });
      continue;
    }
    let agentJson;
    try {
      agentJson = JSON.parse(agentJsonRaw);
    } catch {
      issues.push({
        file: `${dirName}/agent.json`,
        path: "",
        message: "Invalid JSON"
      });
      continue;
    }
    const storageVersion = detectStorageVersion(agentJson);
    if (isVersionNewer(storageVersion, schemaVersion)) {
      issues.push({
        file: `${dirName}/agent.json`,
        path: "metadata.storageVersion",
        message: `storageVersion "${storageVersion}" is newer than the latest version supported by this uip installation ("${schemaVersion}"). Upgrade uip to the latest version.`
      });
      continue;
    }
    const rawTree = await readFilesystemTree(agentDir, fs7);
    const recoveredTree = preMigrationRecovery(rawTree);
    const migrationsToApply = migration.migrations.filter((m) => isVersionNewer(m.to.version, storageVersion));
    let migratedData = recoveredTree;
    for (const m of migrationsToApply) {
      try {
        migratedData = m.apply(migratedData);
      } catch (err) {
        issues.push({
          file: `${dirName}/agent.json`,
          path: "",
          message: `Migration failed (${m.from.version} → ${m.to.version}): ${err instanceof Error ? err.message : String(err)}`
        });
        migratedData = null;
        break;
      }
    }
    if (migratedData === null)
      continue;
    if (migrationsToApply.length > 0) {
      migrationApplied = true;
    }
    const migratedTree = migratedData;
    const agentFile = migratedTree.files.find((f) => f.name === "agent.json");
    if (agentFile) {
      validated.agent = true;
      let agentContent;
      try {
        agentContent = typeof agentFile.content === "string" ? JSON.parse(agentFile.content) : agentFile.content;
      } catch {
        issues.push({
          file: `${dirName}/agent.json`,
          path: "",
          message: "Migrated agent.json is not valid JSON"
        });
        continue;
      }
      const result = migration.currentAgentStorageSchema.safeParse(agentContent);
      if (!result.success && result.error) {
        for (const issue of result.error.issues) {
          issues.push({
            file: `${dirName}/agent.json`,
            path: formatPath(issue.path),
            message: issue.message
          });
        }
      }
    }
    const evalsFolder = migratedTree.folders.find((f) => f.name === "evals");
    const evalSetsFolder = evalsFolder?.folders.find((f) => f.name === "eval-sets");
    if (evalSetsFolder) {
      for (const file of evalSetsFolder.files) {
        if (!file.name.endsWith(".json"))
          continue;
        validated.evalSets++;
        try {
          const content = typeof file.content === "string" ? JSON.parse(file.content) : file.content;
          const result = migration.currentEvaluationSetStorageSchema.safeParse(content);
          if (!result.success && result.error) {
            for (const issue of result.error.issues) {
              issues.push({
                file: `${dirName}/evals/eval-sets/${file.name}`,
                path: formatPath(issue.path),
                message: issue.message
              });
            }
          }
        } catch {
          issues.push({
            file: `${dirName}/evals/eval-sets/${file.name}`,
            path: "",
            message: "Invalid JSON"
          });
        }
      }
    }
    const evaluatorsFolder = evalsFolder?.folders.find((f) => f.name === "evaluators");
    if (evaluatorsFolder) {
      for (const file of evaluatorsFolder.files) {
        if (!file.name.endsWith(".json"))
          continue;
        validated.evaluators++;
        try {
          const content = typeof file.content === "string" ? JSON.parse(file.content) : file.content;
          if (typeof content === "object" && content !== null) {
            for (const issue of validateEvaluatorShape(content)) {
              issues.push({
                file: `${dirName}/evals/evaluators/${file.name}`,
                path: issue.path,
                message: issue.message
              });
            }
          }
        } catch {
          issues.push({
            file: `${dirName}/evals/evaluators/${file.name}`,
            path: "",
            message: "Invalid JSON"
          });
        }
      }
    }
    const resourcesFolder = migratedTree.folders.find((f) => f.name === "resources");
    if (resourcesFolder) {
      validated.resources += resourcesFolder.folders.length;
    }
    pendingTrees.push({ agentDir, tree: migratedTree });
  }
  const valid = issues.length === 0;
  const migratedFiles = [];
  if (valid) {
    for (const { agentDir, tree } of pendingTrees) {
      migratedFiles.push(...collectMigratedFiles(agentDir, tree, fs7));
    }
  }
  return {
    valid,
    schemaVersion,
    issues,
    warnings,
    validated,
    migratedFiles,
    migrationApplied
  };
}
function validateEvaluatorShape(evaluator) {
  const issues = [];
  for (const field of [
    "fileName",
    "id",
    "name",
    "description",
    "category",
    "type",
    "targetOutputKey",
    "createdAt",
    "updatedAt"
  ]) {
    if (evaluator[field] === undefined || evaluator[field] === null) {
      issues.push({
        path: field,
        message: `Required field "${field}" is missing`
      });
    }
  }
  const { category, type } = evaluator;
  if (category === 0) {
    if (type !== 1 && type !== 6) {
      issues.push({
        path: "type",
        message: `Deterministic evaluator (category 0) must have type 1 or 6, got ${type}`
      });
    }
  } else if (category === 1) {
    if (type !== 5 && type !== 8 && type !== 9) {
      issues.push({
        path: "type",
        message: `LLM evaluator (category 1) must have type 5, 8, or 9, got ${type}`
      });
    }
    if (!evaluator.prompt)
      issues.push({
        path: "prompt",
        message: "LLM evaluator requires a prompt"
      });
    if (!evaluator.model)
      issues.push({
        path: "model",
        message: "LLM evaluator requires a model"
      });
  } else if (category === 3) {
    if (type !== 7) {
      issues.push({
        path: "type",
        message: `Simulation evaluator (category 3) must have type 7, got ${type}`
      });
    }
    if (!evaluator.prompt)
      issues.push({
        path: "prompt",
        message: "Simulation evaluator requires a prompt"
      });
    if (!evaluator.model)
      issues.push({
        path: "model",
        message: "Simulation evaluator requires a model"
      });
  } else if (category !== undefined) {
    issues.push({
      path: "category",
      message: `Invalid evaluator category: ${category}. Must be 0, 1, or 3`
    });
  }
  return issues;
}

