async function findFilesWithExtension(dir, ext) {
  const fs7 = getFileSystem();
  const results = [];
  const entries = await fs7.readdir(dir);
  for (const entry of entries) {
    const fullPath = fs7.path.join(dir, entry);
    const s = await fs7.stat(fullPath);
    if (s?.isDirectory()) {
      results.push(...await findFilesWithExtension(fullPath, ext));
    } else if (entry.endsWith(ext)) {
      results.push(fullPath);
    }
  }
  return results;
}
async function uploadNupkgsToOrchestrator(solutionZipPath, loginStatus, folderOrgUnitId) {
  const fs7 = getFileSystem();
  const extractDir = fs7.path.join(fs7.env.tmpdir(), `agent-nupkg-extract-${Date.now()}`);
  await fs7.mkdir(extractDir);
  await extractArchive(solutionZipPath, extractDir);
  const nupkgFiles = await findFilesWithExtension(extractDir, ".nupkg");
  if (nupkgFiles.length === 0) {
    throw new Error("No .nupkg files found in solution package");
  }
  const baseUrl = `${loginStatus.baseUrl}/${loginStatus.organizationId}/${loginStatus.tenantName}/orchestrator_`;
  const orgUnitId = folderOrgUnitId ?? loginStatus.organizationUnitId?.toString();
  const releases = [];
  for (const nupkgFile of nupkgFiles) {
    const fileBuffer = await fs7.readFile(nupkgFile);
    if (!fileBuffer) {
      throw new Error(`Failed to read nupkg file: ${nupkgFile}`);
    }
    const fileName = fs7.path.basename(nupkgFile);
    const formData = new FormData;
    formData.append("file", new Blob([fileBuffer]), fileName);
    const headers = {
      Authorization: `Bearer ${loginStatus.accessToken}`
    };
    if (orgUnitId) {
      headers["X-UIPATH-OrganizationUnitId"] = orgUnitId;
    }
    const uploadResp = await fetch(`${baseUrl}/odata/Processes/UiPath.Server.Configuration.OData.UploadPackage`, { method: "POST", headers, body: formData });
    if (!uploadResp.ok) {
      const errText = await uploadResp.text();
      throw new Error(`Failed to upload ${fileName}: ${uploadResp.status} ${errText}`);
    }
    const uploadResult = await uploadResp.json();
    const item = uploadResult.value?.[0];
    if (item?.Body) {
      const body = JSON.parse(item.Body);
      OutputFormatter.log({
        Message: `Uploaded ${body.Id} v${body.Version}`
      });
      const releaseResp = await fetch(`${baseUrl}/odata/Releases`, {
        method: "POST",
        headers: {
          ...headers,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          Name: fs7.path.basename(body.Id).replace(/^.*\.agent\./, ""),
          ProcessKey: body.Id,
          ProcessVersion: body.Version
        })
      });
      if (releaseResp.status === 201) {
        const release = await releaseResp.json();
        releases.push({
          name: release.Name,
          key: release.Key,
          processKey: release.ProcessKey
        });
      }
    }
  }
  return { releases };
}
async function resolveAgentUisPath(inputPath, packageNameOverride) {
  const fs7 = getFileSystem();
  const absPath = fs7.path.resolve(inputPath);
  const pathExists = await fs7.exists(absPath);
  if (!pathExists || absPath.endsWith(".uis")) {
    return { absPath, uisPath: absPath };
  }
  const projectService = new AgentProjectService;
  const validation = await projectService.validateProjectStructure(absPath);
  if (!validation.valid) {
    throw new Error(`Invalid agent project:
${validation.errors.join(`
`)}`);
  }
  const agent = await projectService.readAgentJson(absPath);
  const packageName = packageNameOverride ?? agent.metadata.name ?? fs7.path.basename(absPath);
  const tempDir = fs7.path.join(fs7.env.tmpdir(), `agent-publish-${Date.now()}`);
  await fs7.mkdir(tempDir);
  const uisPath = fs7.path.join(tempDir, `${packageName}.uis`);
  await createArchive(absPath, uisPath);
  OutputFormatter.log({
    Message: `Packed agent to ${uisPath}`
  });
  return { absPath, uisPath };
}
async function publishDirectAgentPackage(zipPath, loginStatus, tenantName, packageName, packageVersion, folderId) {
  OutputFormatter.log({
    Message: "Uploading packages directly to Orchestrator..."
  });
  const result = await uploadNupkgsToOrchestrator(zipPath, { ...loginStatus, tenantName }, folderId);
  OutputFormatter.success({
    Result: RESULTS.Success,
    Code: "AgentPublish",
    Data: {
      Status: "Published to Orchestrator (direct)",
      Name: packageName,
      Version: packageVersion,
      Releases: result.releases.map((r) => ({
        Name: r.name,
        Key: r.key,
        ProcessKey: r.processKey
      }))
    }
  });
  const firstRelease = result.releases[0];
  trackShipSucceeded({
    ship_kind: "publish",
    target: folderId ? "orchestrator_folder_package_feed" : "orchestrator_tenant_package_feed",
    project_type: "low_code_agent",
    command_name: "uip.agent.publish",
    artifact_correlation_key: firstRelease?.processKey ?? firstRelease?.key ?? `${packageName}:${packageVersion}`,
    package_name: packageName,
    package_version: packageVersion,
    folder_key: folderId
  });
}
async function publishSolutionAgentPackage(zipPath, loginStatus, tenantName, packageName, packageVersion, locationKey) {
  const fs7 = getFileSystem();
  OutputFormatter.log({
    Message: "Publishing to Orchestrator..."
  });
  const fileBuffer = await fs7.readFile(zipPath);
  if (!fileBuffer) {
    throw new Error(`Failed to read solution zip: ${zipPath}`);
  }
  const basePath = `${loginStatus.baseUrl}/${loginStatus.organizationId}/${tenantName}/automationsolutions_`;
  const configuration = new Configuration({
    basePath,
    accessToken: loginStatus.accessToken
  });
  const api = new PackagesApi(configuration);
  const packageVersionKey = await api.packagesUpload({
    locationKey,
    body: fileBuffer
  });
  OutputFormatter.success({
    Result: RESULTS.Success,
    Code: "AgentPublish",
    Data: {
      Status: "Published successfully",
      Name: packageName,
      Version: packageVersion,
      PackageVersionKey: packageVersionKey
    },
    Instructions: "Deploy via Orchestrator UI or use --direct flag for direct upload."
  });
  trackShipSucceeded({
    ship_kind: "publish",
    target: "tenant_solution_feed",
    project_type: "low_code_agent",
    command_name: "uip.agent.publish",
    artifact_correlation_key: packageVersionKey,
    package_version_key: packageVersionKey,
    package_name: packageName,
    package_version: packageVersion
  });
}
async function publishPackedAgentPackage(zipPath, loginStatus, tenantName, packageName, options) {
  if (options.direct) {
    await publishDirectAgentPackage(zipPath, loginStatus, tenantName, packageName, options.packageVersion, options.folderId);
    return;
  }
  await publishSolutionAgentPackage(zipPath, loginStatus, tenantName, packageName, options.packageVersion, options.locationKey);
}
var registerPublishCommand = (program) => {
  program.command("publish").description("[DEPRECATED] Pack and publish an agent to UiPath Orchestrator").argument("[path]", "Path to agent project directory or .uis file", ".").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant>")).option("-l, --location-key <guid>", "Location key (optional GUID)").option("-n, --name <name>", "Package name (default: agent name)").option("--package-version <version>", "Package version (default: 1.0.0)", "1.0.0").option("--folder-id <id>", "Orchestrator folder org unit ID for direct upload").option("--direct", "Upload nupkg directly to Orchestrator (bypasses solution deployment)").option("--login-validity <minutes>", "Minimum minutes before token expiration", (v) => Number.parseInt(v, 10), 10).examples(PUBLISH_EXAMPLES).trackedAction(processContext, async (inputPath, options) => {
    const [error] = await catchError((async () => {
      const fs7 = getFileSystem();
      const loginStatus = await getLoginStatusAsync({
        ensureTokenValidityMinutes: options.loginValidity
      });
      if (loginStatus.loginStatus !== "Logged in" || !loginStatus.accessToken || !loginStatus.baseUrl || !loginStatus.organizationId) {
        throw new Error("Not logged in. Run 'uip login' first.");
      }
      const { absPath, uisPath } = await resolveAgentUisPath(inputPath, options.name);
      const { execFile: execFile7 } = await import("node:child_process");
      const { promisify: promisify7 } = await import("node:util");
      const execFileAsync5 = promisify7(execFile7);
      const packOutputDir = fs7.path.join(fs7.env.tmpdir(), `agent-pack-output-${Date.now()}`);
      await fs7.mkdir(packOutputDir);
      const packageName = options.name ?? fs7.path.basename(absPath, ".uis");
      const uipPath = process.argv[1];
      if (!uipPath) {
        throw new Error("Could not determine CLI entry point from process.argv.");
      }
      OutputFormatter.log({
        Message: "Packing solution..."
      });
      const [packError] = await catchError(execFileAsync5(process.execPath, [
        uipPath,
        "solution",
        "pack",
        uisPath,
        packOutputDir,
        "--name",
        packageName,
        "--version",
        options.packageVersion,
        "--output",
        "json"
      ], { timeout: 120000 }));
      const outputFiles = await fs7.readdir(packOutputDir);
      const zipFile = outputFiles.find((f) => f.endsWith(".zip"));
      if (!zipFile) {
        if (packError) {
          const stderr = packError?.stderr ?? "";
          const stdout = packError?.stdout ?? "";
          throw new Error(`Solution pack failed: ${stderr || stdout || packError.message}`);
        }
        throw new Error(`Solution pack did not produce a .zip file in ${packOutputDir}`);
      }
      const zipPath = fs7.path.join(packOutputDir, zipFile);
      const tenantName = options.tenant ?? loginStatus.tenantName;
      if (!tenantName) {
        throw new Error("Tenant must be selected during login. Run 'uip login' or 'uip login tenant set <tenant>'.");
      }
      await publishPackedAgentPackage(zipPath, loginStatus, tenantName, packageName, options);
    })());
    if (error) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Failed to publish agent",
        Instructions: error.message
      });
      processContext.exit(1);
    }
  });
};

