async function shellifyParentFlow(fs7, agentDir, agentProjectId) {
  const parentDir = fs7.path.dirname(agentDir);
  const [listErr, entries] = await catchError(fs7.readdir(parentDir));
  if (listErr || !entries)
    return null;
  const flowFile = entries.find((e) => e.endsWith(".flow"));
  if (!flowFile)
    return null;
  const flowPath = fs7.path.join(parentDir, flowFile);
  const [readErr, raw] = await catchError(fs7.readFile(flowPath, "utf-8"));
  if (readErr || !raw)
    return null;
  let flow;
  try {
    flow = JSON.parse(raw);
  } catch {
    return null;
  }
  const result = shellifyInlineAgents(flow, {
    onlyAgentSource: agentProjectId
  });
  if (!result.changed)
    return null;
  const [writeErr] = await catchError(fs7.writeFile(flowPath, JSON.stringify(flow, null, 2)));
  if (writeErr) {
    logger.warn(`Could not write shell-ified ${flowFile}; leaving the embed in place (bundle/upload will normalize it): ${writeErr instanceof Error ? writeErr.message : String(writeErr)}`);
    return null;
  }
  return {
    strippedResourceNodes: result.agents.reduce((sum, a) => sum + a.strippedResourceNodes, 0)
  };
}
