var LLM_AS_JUDGE_VALIDATOR = "llm_as_judge";
async function loadGuardrailDefinitions(fs7, projectPath) {
  const agentConfig = await readAgentConfig(fs7, projectPath);
  if (agentConfig === undefined || !hasBuiltInGuardrail(agentConfig)) {
    return;
  }
  const [err2, definitions] = await catchError(getGuardrailDefinitions());
  if (err2 || definitions === undefined) {
    return;
  }
  return definitions.map(toReviewerDefinition);
}
async function loadLlmJudgeModels(fs7, projectPath) {
  const agentConfig = await readAgentConfig(fs7, projectPath);
  if (agentConfig === undefined || !hasLlmAsJudgeGuardrail(agentConfig)) {
    return;
  }
  const [err2, models2] = await catchError(getLlmJudgeModelIds());
  if (err2 || models2 === undefined) {
    return;
  }
  return models2;
}
async function readAgentConfig(fs7, projectPath) {
  const [readErr, raw] = await catchError(fs7.readFile(fs7.path.join(projectPath, "agent.json"), "utf-8"));
  if (readErr || raw == null) {
    return;
  }
  const [parseErr, parsed] = await catchError(Promise.resolve().then(() => JSON.parse(raw)));
  if (parseErr || typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    return;
  }
  return parsed;
}
function hasLlmAsJudgeGuardrail(config2) {
  return guardrailEntries(config2).some((guardrail) => guardrail.validatorType === LLM_AS_JUDGE_VALIDATOR);
}
function guardrailEntries(config2) {
  if (!Array.isArray(config2.guardrails)) {
    return [];
  }
  return config2.guardrails.filter((entry) => typeof entry === "object" && entry !== null);
}
function hasBuiltInGuardrail(config2) {
  return guardrailEntries(config2).some((guardrail) => guardrail.$guardrailType === "builtInValidator" || typeof guardrail.validatorType === "string");
}
function toReviewerDefinition(d) {
  return {
    validator: d.validator,
    allowedScopes: d.allowedScopes,
    parameters: d.parameters.map((p) => ({
      type: p.type,
      id: p.id,
      required: p.required,
      ...p.options ? { options: p.options } : {},
      ...p.keySource ? { keySource: p.keySource } : {},
      ...p.min != null ? { min: p.min } : {},
      ...p.max != null ? { max: p.max } : {},
      ...p.step != null ? { step: p.step } : {}
    }))
  };
}

