    const projectPath = fs7.path.resolve(targetPath);
    let categories;
    if (options.checks !== undefined) {
      const parts = options.checks.split(",").map((s) => s.trim()).filter((s) => s.length > 0);
      if (parts.length === 0) {
        const knownCategories = listCategories().join(", ");
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Code: CODES.invalidChecks,
          Message: "`--checks` requires at least one category.",
          Instructions: `Known categories: ${knownCategories}. Omit --checks to run all rules.`
        });
        processContext.exit(1);
        return;
      }
      categories = parts;
    }
    const [guardrailDefinitions2, llmJudgeModels] = await Promise.all([
      loadGuardrailDefinitions(fs7, projectPath),
      loadLlmJudgeModels(fs7, projectPath)
    ]);
    const [err2, outcome] = await catchError(reviewLowCodeAgent(projectPath, { categories, guardrailDefinitions: guardrailDefinitions2, llmJudgeModels }, fs7));
    if (err2) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Code: CODES.failed,
        Message: `Review failed: ${extractErrorMessageSync(err2)}`,
        Instructions: "Verify the project path exists and is a readable agent project. " + "Run `uip agent review --help` for usage."
      });
      processContext.exit(1);
      return;
    }
