async function addIntegrationToolWithIS(name, options) {
  const { IntegrationServiceClient: ISClient } = await import("./is-client-a1hbz77f.js");
  const { IntegrationToolService } = await import("./integration-tool-service-n214kzdn.js");
  const isClient = await ISClient.create();
  const service = new IntegrationToolService(isClient);
  const tool = await service.addTool({
    name,
    description: options.description,
    connectorKey: options.connector,
    objectName: options.objectName,
    connectionId: options.connectionId,
    method: options.method,
    guardrailPolicies: options.guardrailPolicies,
    projectPath: options.path
  });
  if (options.connectionId) {
    const [debugError] = await catchError((async () => {
      const { getLoginStatusAsync: getLoginStatusAsync3 } = await import("./index-byw2z4xp.js");
      const loginStatus = await getLoginStatusAsync3();
      const connection = await isClient.getConnectionById(options.connectionId);
      const userId = extractJwtSub(loginStatus.accessToken);
      if (userId && loginStatus.tenantId) {
        const { AgentProjectService: AgentProjectService2 } = await import("./agent-project-service-j4pgc7gk.js");
        const projectService = new AgentProjectService2;
        const existing = await projectService.readDebugOverwrites(options.path, userId);
        const folderKey = connection.folder?.key ?? "00000000-0000-0000-0000-000000000000";
        const folderName = connection.folder?.name ?? "";
        const folderPath = loginStatus.organizationId ? `${loginStatus.organizationId}.${folderKey}` : folderKey;
        const newResource = {
          solutionResourceKey: options.connectionId,
          resourceName: connection.name ?? options.connector,
          folderKey,
          folderFullyQualifiedName: folderName,
          folderPath
        };
        let resources = [newResource];
        if (existing?.tenants?.[0]?.resources) {
          const existingResources = existing.tenants[0].resources.map((r) => ({
            solutionResourceKey: r.solutionResourceKey,
            resourceName: r.overwrite?.resourceName,
            folderKey: r.overwrite?.folderKey,
            folderFullyQualifiedName: r.overwrite?.folderFullyQualifiedName,
            folderPath: r.overwrite?.folderPath
          }));
          const keys = new Set(existingResources.map((r) => r.solutionResourceKey));
          if (!keys.has(options.connectionId)) {
            resources = [...existingResources, newResource];
          } else {
            resources = existingResources;
          }
        }
        await projectService.writeDebugOverwrites(options.path, {
          userId,
          tenantKey: loginStatus.tenantId,
          resources
        });
      }
    })());
  }
  return tool;
}
async function loadGuardrailPolicies(value) {
  if (value.trim().length === 0) {
    throw new Error("Guardrails value cannot be empty. Provide a JSON policy object, JSON array, or path to a JSON file.");
  }
  const [parseError, parsed] = catchError(() => JSON.parse(value));
  if (!parseError) {
    return normalizeGuardrailPolicies(parsed);
  }
  const fs7 = getFileSystem();
  const filePath = fs7.path.resolve(value);
  if (!await fs7.exists(filePath)) {
    throw new Error("Invalid guardrails value. Provide a JSON object, JSON array, or path to a JSON file.");
  }
  const raw = await fs7.readFile(filePath, "utf-8");
  if (raw.trim().length === 0) {
    throw new Error(`Guardrails file is empty: ${filePath}`);
  }
  const [fileParseError, fileParsed] = catchError(() => JSON.parse(raw));
  if (fileParseError) {
    throw new Error(`Invalid guardrails JSON in ${filePath}: ${fileParseError.message}`);
  }
  return normalizeGuardrailPolicies(fileParsed);
}
function normalizeGuardrailPolicies(value) {
  const policies = Array.isArray(value) ? value : isRecord3(value) && Array.isArray(value.policies) ? value.policies : isRecord3(value) ? [value] : undefined;
  if (!policies) {
    throw new Error("Guardrails must be a JSON policy object, an array of policies, or an object with a policies array.");
  }
  return policies.map(normalizeGuardrailPolicy);
}
function isRecord3(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function normalizeGuardrailPolicy(value) {
  if (!isRecord3(value) || !instanceOfAgentGuardrailPolicy(value) || !isRecord3(value.action)) {
    throw new Error("Each guardrail policy must be a JSON object with an action object.");
  }
  return value;
}
function extractJwtSub(token) {
  if (!token)
    return;
  const parts = token.split(".");
  if (parts.length < 2)
    return;
  const payload = parts[1];
  const decoded = atob(payload.replace(/-/g, "+").replace(/_/g, "/"));
  const [error51, claims] = catchError(() => JSON.parse(decoded));
  if (error51) {
    return;
  }
  return claims.sub;
}

